        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    def largest_prime(lst):
        max_prime = -1
        for num in lst:
            if is_prime(num) and num > max_prime:
                max_prime = num
        return max_prime

    def sum_of_digits(n):
        return sum(int(digit) for digit in str(n))

    largest = largest_prime(lst)
    if largest == -1:
        return 0
    return sum_of_digits(largest)

